import{_ as i,H as t,f as l,i as a}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"53 | RESTfulWebServices（17）：如何进行Spike的架构愿景细化？","description":"","frontmatter":{},"headers":[{"level":2,"title":"回顾架构愿景与任务列表","slug":"回顾架构愿景与任务列表","link":"#回顾架构愿景与任务列表","children":[]},{"level":2,"title":"细化任务列表","slug":"细化任务列表","link":"#细化任务列表","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"徐昊·TDD项目实战70讲/53｜RESTfulWebServices（17）：如何进行Spike的架构愿景细化？.md","filePath":"徐昊·TDD项目实战70讲/53｜RESTfulWebServices（17）：如何进行Spike的架构愿景细化？.md","lastUpdated":1795563222000}'),r={name:"徐昊·TDD项目实战70讲/53｜RESTfulWebServices（17）：如何进行Spike的架构愿景细化？.md"};function s(p,e,o,n,E,u){return t(),l("div",null,[...e[0]||(e[0]=[a('<h1 id="_53-restfulwebservices-17-如何进行spike的架构愿景细化" tabindex="-1">53 | RESTfulWebServices（17）：如何进行Spike的架构愿景细化？ <a class="header-anchor" href="#_53-restfulwebservices-17-如何进行spike的架构愿景细化" aria-label="Permalink to &quot;53 | RESTfulWebServices（17）：如何进行Spike的架构愿景细化？&quot;">​</a></h1><p>你好，我是徐昊。今天我们继续使用 TDD 的方式实现 RESTful Web Services。</p><h2 id="回顾架构愿景与任务列表" tabindex="-1">回顾架构愿景与任务列表 <a class="header-anchor" href="#回顾架构愿景与任务列表" aria-label="Permalink to &quot;回顾架构愿景与任务列表&quot;">​</a></h2><p>目前我们已经实现了 ResourceRouter，整体的架构愿景如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/53/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/53/1.png" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/53/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/53/2.png" alt=""></a></p><h2 id="细化任务列表" tabindex="-1">细化任务列表 <a class="header-anchor" href="#细化任务列表" aria-label="Permalink to &quot;细化任务列表&quot;">​</a></h2><p>沿着调用栈的顺序，就要进入 RootResource/Resource/ResourceMethod 的开发中。未经细化的任务列表如下：</p><ul><li><p>Resource/RootResource/ResourceMethod</p></li><li><p>在处理请求派分时，可以支持多级子资源（Sub-Resource）</p></li><li><p>在处理请求派分时，可以根据客户端提供的超媒体类型，选择对应的资源方法（Resource Method）</p></li><li><p>在处理请求派分时，可以根据客户端提供的 Http 方法，选择对应的资源方法</p></li><li><p>资源方法可以返回 Java 对象，由 Runtime 自行推断正确的返回状态</p></li><li><p>资源方法可以不明确指定返回的超媒体类型，由 Runtime 自行推断，比如，资源方法标注了 Produces 标注，那么就使用标注提供的超媒体类型等</p></li><li><p>资源方法可按找期望的类型，访问 Http 请求的内容</p></li><li><p>资源对象和资源方法可接受环境组件的注入</p></li></ul><p>而在当前架构愿景下，RootResource/Resource/ResourceMethod 都需要使用 UriTemplate、UriInfoBuilder 作为支撑。其中，UriInfoBuilder 还没有具体的接口设计，那么我们可以先实现UriTemplate。视频演示如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/53/3.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/53/3.jpeg" alt=""></a></p><p>接下来，我们可以细化 UriTemplate 的任务：</p><ul><li><p>UriTemplate</p></li><li><p>匹配无参数的 Uri 模版</p></li><li><p>如果 Uri 可以与模版匹配，则返回匹配结果</p></li><li><p>如果 Uri 不能与模版匹配，则返回 Optional.empty</p></li><li><p>匹配带参数的 Uri 模版</p></li><li><p>如果 Uri 可以与模版匹配，按照指定参数从 Uri 中提取值</p></li><li><p>参数可以通过正则表达式指定格式</p></li><li><p>如果参数重复定义，则抛出异常</p></li><li><p>模版匹配的结果可以比较大小</p></li><li><p>如果匹配的非参字符多，则优先（长的优先）</p></li><li><p>如果匹配的非参数字符一样，匹配的分组多，则优先（参数优先）</p></li><li><p>如果匹配的分组一样多，指定格式参数匹配多的优先（指定格式参数优先）</p></li></ul><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>如何根据 variable 获取值？</p><p>欢迎把你的想法分享在留言区，也欢迎把你的项目代码分享出来。相信经过你的思考与实操，学习效果会更好！</p>',16)])])}const _=i(r,[["render",s]]);export{h as __pageData,_ as default};
